class TrainingPairBuilder:
    def __init__(self):
        self.pairs = []  # list of (text_a, text_b, label)

    def add_pair(self, text_a: str, text_b: str, label: float):
        if isinstance(label, bool) or not isinstance(label, (int, float)):
            raise ValueError("label must be a number between 0.0 and 1.0")
        if not 0.0 <= label <= 1.0:
            raise ValueError("label must be between 0.0 and 1.0")
        self.pairs.append((text_a, text_b, float(label)))

    def get_positives(self, threshold: float = 0.5) -> list:
        return [p for p in self.pairs if p[2] >= threshold]

    def get_negatives(self, threshold: float = 0.5) -> list:
        return [p for p in self.pairs if p[2] < threshold]

    def summary(self, threshold: float = 0.5) -> dict:
        total = len(self.pairs)
        avg = sum(p[2] for p in self.pairs) / total if total else 0.0
        return {
            'total': total,
            'positives': len(self.get_positives(threshold)),
            'negatives': len(self.get_negatives(threshold)),
            'avg_label': avg,
        }


# Test it:
builder = TrainingPairBuilder()
builder.add_pair("heart attack", "myocardial infarction", 0.95)
builder.add_pair("heart attack", "knee surgery", 0.1)
builder.add_pair("chest pain", "angina symptoms", 0.85)
builder.add_pair("blood test", "car repair", 0.0)

print(len(builder.get_positives()))
print(len(builder.get_negatives()))
s = builder.summary()
print(s['total'])
print(round(s['avg_label'], 2))

class FineTuneEvaluator:
    def __init__(self):
        self.test_pairs = []  # list of (text_a, text_b, expected_score)

    def add_test_pair(self, text_a: str, text_b: str, expected_score: float):
        if not isinstance(expected_score, (int, float)) or isinstance(expected_score, bool):
            raise ValueError("expected_score must be a number")
        if not 0.0 <= expected_score <= 1.0:
            raise ValueError("expected_score must be between 0.0 and 1.0")
        self.test_pairs.append((text_a, text_b, float(expected_score)))

    def evaluate(self, encode_fn) -> float:
        if not self.test_pairs:
            return 0.0
        total = 0.0
        for text_a, text_b, expected in self.test_pairs:
            predicted = encode_fn(text_a, text_b)["similarity"]
            total += abs(predicted - expected)
        return total / len(self.test_pairs)

    def compare(self, base_encode_fn, tuned_encode_fn) -> dict:
        base_error = self.evaluate(base_encode_fn)
        tuned_error = self.evaluate(tuned_encode_fn)
        return {
            "base_error": base_error,
            "tuned_error": tuned_error,
            "improvement": base_error - tuned_error,
        }


# Test it:
eval = FineTuneEvaluator()
eval.add_test_pair("heart attack", "MI", 0.9)
eval.add_test_pair("heart attack", "knee pain", 0.1)

# Simulate base model (mediocre on domain)
def base_fn(a, b):
    return {"similarity": 0.5}

# Simulate fine-tuned model (better on domain)
def tuned_fn(a, b):
    if "heart" in a and "MI" in b:
        return {"similarity": 0.85}
    return {"similarity": 0.15}

result = eval.compare(base_fn, tuned_fn)
print(round(result['base_error'], 2))
print(round(result['tuned_error'], 2))
print(result['improvement'] > 0)
